/* ---------- 4. Layout ---------------------------------------------------- */

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--space-6);
}

/* Form left, results right. The form/results row is its own box so the sticky form stops at
   the end of the results and never covers Saved calculations (D-69). */
.layout-main {
  display: grid;
  grid-template-columns: minmax(0, 4fr) minmax(0, 6fr);
  gap: var(--space-6);
  align-items: start;
}

.card {
  min-width: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  padding: var(--space-7);
  box-shadow: var(--shadow-card);
}

.history-card {
  grid-column: 1 / -1;
}

/* The form stays in view while the results scroll (owner request, D-69). Only side by side
   (≥ 769px) and only when the window is tall enough to show the whole form, so Calculate is
   never out of reach. It stops at the end of the results row, above Saved calculations. */
@media (min-width: 769px) and (min-height: 820px) {
  .form-card {
    position: sticky;
    top: var(--space-6);
  }
}

/* ---------- 5. Form ------------------------------------------------------ */

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 18px;
  min-width: 0;
}

label {
  font-size: 14px;
  font-weight: 650;
}
  box-shadow: none;
}

/* ---------- 11. Tablet + phone (≤ 768px) --------------------------------- */

@media (max-width: 768px) {
  .page {
    padding: 28px 24px 40px;
  }
  .layout,
  .layout-main {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-4);
  }
  .history-card {
    grid-column: auto;
  }
  .card {
    padding: var(--space-6);
    border-radius: 26px;
  }
}

@media (max-width: 560px) {
  .page {
    padding: 20px 16px 32px;
    line-height: 1.25;
  }
  .figure.headline {
    padding: 18px 18px var(--space-5);
  }

  .schedule h2 {
    margin-top: var(--space-6);
  }
  .schedule th,
  .schedule td {
    padding-left: 14px;
    padding-right: 14px;
  }
  /* Month column stays put while the table scrolls sideways (proposal P3; pure CSS). */
  .schedule th:first-child,
  .schedule td:first-child {
    position: sticky;
    left: 0;
    z-index: 2;
  }
  .schedule th:first-child {
    z-index: 3;
  }
  .schedule td:first-child {
    background: var(--surface);
    box-shadow: 1px 0 0 var(--border);
  }
  .schedule tbody tr:nth-child(even) td:first-child {
    background: var(--band);
  }
  color: var(--text);
  background: var(--bg);
  font-size: 18px;
  font-weight: 650;
}

/* ---------- 14. Charts (D-65, D-68) -------------------------------------- */

.chart-block {
  margin-top: var(--space-6);
  min-width: 0;
}

.chart-title {
  margin: 0 0 var(--space-3);
  font-size: 16px;
  font-weight: 750;
  letter-spacing: -0.01em;
  color: var(--text);
}

figure.chart {
  margin: 0;
  min-width: 0;
  padding: var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-tile);
  background: var(--surface);
}

.chart figcaption {
  margin-top: var(--space-3);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text);
  overflow-wrap: anywhere;
}

.chart-plot-wrap {
  position: relative;
}

.chart-plot {
  display: block;
  width: 100%;
  height: 140px;
  cursor: crosshair;
}

.mark-principal {
  fill: var(--chart-principal);
}
.mark-interest {
  fill: var(--chart-interest);
}

/* Decorative highlight of the hovered band; not a data mark. */
.chart-hover-band {
  fill: var(--text);
  opacity: 0.08;
  pointer-events: none;
}

.chart-axis {
  display: flex;
  justify-content: space-between;
  margin-top: var(--space-1);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px var(--space-4);
  margin: var(--space-3) 0 0;
  padding: 0;
  list-style: none;
  font-size: 13px;
  font-weight: 650;
  color: var(--text);
}
.chart-legend li {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

.swatch {
  width: 12px;
  height: 12px;
  border-radius: 4px;
}
.swatch-principal {
  background: var(--chart-principal);
}
.swatch-interest {
  background: var(--chart-interest);
}

/* Pointer tooltip: never intercepts the pointer, always inside the plot's width. */
.chart-tooltip {
  position: absolute;
  top: var(--space-1);
  z-index: 4;
  max-width: 100%;
  padding: 6px 10px;
  border: 1px solid var(--input-border);
  border-radius: 10px;
  background: var(--surface);
  box-shadow: var(--shadow-card);
  color: var(--text);
  font-size: 13px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}

/* Cost breakdown: flex weights are the two percentages, with a 2px surface gap. */
.cost-bar {
  display: flex;
  gap: 2px;
  height: 18px;
}
.cost-segment {
  display: block;
  flex-basis: 0;
  min-width: 0;
  height: 100%;
}
.cost-segment[data-segment='loan'] {
  background: var(--chart-principal);
  border-radius: 6px 0 0 6px;
}
.cost-segment[data-segment='interest'] {
  background: var(--chart-interest);
  border-radius: 0 6px 6px 0;
}
.cost-segment:only-child {
  border-radius: 6px;
}

/* Yearly summary table: same rhythm as the schedule, not a separate scroll stop. */
.yearly-table {
  width: 100%;
  margin-top: var(--space-4);
  border-collapse: separate;
  border-spacing: 0;
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}
.yearly-table th {
  padding: var(--space-2) var(--space-3);
  background: var(--wash);
  border-bottom: 1.5px solid var(--input-border);
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-align: right;
  text-transform: uppercase;
}
.yearly-table td {
  padding: 8px var(--space-3);
  border-bottom: 1px solid var(--border);
  text-align: right;
  overflow-wrap: anywhere;
}
.yearly-table th:first-child,
.yearly-table td:first-child {
  text-align: left;
}
.yearly-table tbody tr:nth-child(even) td {
  background: var(--band);
}

@media (max-width: 560px) {
  figure.chart {
    padding: var(--space-3);
  }
  .chart-plot {
    height: 120px;
  }
  .yearly-table th,
  .yearly-table td {
    padding-left: var(--space-2);
    padding-right: var(--space-2);
  }
}

