// Hover geometry follows D-66: item k of n sits at x = (k - 0.5) / n of the width of [data-hit-area].
import type { Locator, Page } from '@playwright/test'
import { box, expect, type Rgb } from './fixtures'

export const CHART_TITLES = [
  'Cost breakdown',
